CREATE TABLE care_assessments (id {PK}, patient_id BIGINT NOT NULL REFERENCES patients(id), assessed_by BIGINT NOT NULL REFERENCES users(id), assessed_at TEXT NOT NULL, summary_enc TEXT NOT NULL, recommendation_enc TEXT, created_at TEXT NOT NULL);
CREATE TABLE care_plans (id {PK}, patient_id BIGINT NOT NULL REFERENCES patients(id), title TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'draft', published INTEGER NOT NULL DEFAULT 0, version INTEGER NOT NULL DEFAULT 1, created_by BIGINT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE care_plan_tasks (id {PK}, care_plan_id BIGINT NOT NULL REFERENCES care_plans(id), description TEXT NOT NULL, frequency TEXT, active INTEGER NOT NULL DEFAULT 1, created_by BIGINT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL);
CREATE TABLE homecare_visits (id {PK}, patient_id BIGINT NOT NULL REFERENCES patients(id), care_plan_id BIGINT REFERENCES care_plans(id), visit_type TEXT NOT NULL, scheduled_start TEXT NOT NULL, scheduled_end TEXT NOT NULL, location_area TEXT, address_enc TEXT, status TEXT NOT NULL DEFAULT 'scheduled', created_by BIGINT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX idx_visits_start ON homecare_visits(scheduled_start);
CREATE TABLE visit_assignments (id {PK}, visit_id BIGINT NOT NULL REFERENCES homecare_visits(id), caregiver_id BIGINT NOT NULL REFERENCES users(id), status TEXT NOT NULL DEFAULT 'offered', assigned_by BIGINT NOT NULL REFERENCES users(id), assigned_at TEXT NOT NULL, responded_at TEXT);
CREATE INDEX idx_assign_caregiver ON visit_assignments(caregiver_id, status);
CREATE TABLE visit_records (id {PK}, visit_id BIGINT NOT NULL UNIQUE REFERENCES homecare_visits(id), started_at TEXT, completed_at TEXT, report_enc TEXT, documented_by BIGINT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL);
CREATE TABLE visit_task_records (id {PK}, visit_record_id BIGINT NOT NULL REFERENCES visit_records(id), task_id BIGINT NOT NULL REFERENCES care_plan_tasks(id), done INTEGER NOT NULL, note_enc TEXT, recorded_at TEXT NOT NULL, UNIQUE (visit_record_id, task_id));
